BEGIN;
SELECT plan(36);

ALTER SEQUENCE app.project_expense_number_seq RESTART WITH 1;

INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
VALUES
  ('00000000-0000-0000-0000-000000007401','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-a.74@example.test','',now(),'{}','{}',now(),now()),
  ('00000000-0000-0000-0000-000000007402','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-b.74@example.test','',now(),'{}','{}',now(),now());
SELECT * FROM app.bootstrap_first_owner('00000000-0000-0000-0000-000000007401','owner-a.74@example.test','Owner A Seventy Four',decode('7474747474747474747474747474747474747474747474747474747474747474','hex'),'req-74','corr-74');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000007401',true);
SELECT public.activate_current_invited_owner();

INSERT INTO app.contractor_profiles (legal_name, display_name, default_reporting_currency_code, time_zone, created_by, updated_by)
VALUES ('Expense Contractor','Expense Contractor','USD','Asia/Singapore',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'));
INSERT INTO app.users (id, auth_subject, email, user_type, status, is_active, created_by, updated_by)
VALUES ('10000000-0000-0000-0000-000000007402','00000000-0000-0000-0000-000000007402','owner-b.74@example.test','STAFF','ACTIVE',true,(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'));
INSERT INTO app.user_profiles (user_id, full_name, created_by, updated_by) VALUES ('10000000-0000-0000-0000-000000007402','Owner B',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'));
INSERT INTO app.user_roles (user_id, role_code, assigned_by, is_active) VALUES ('10000000-0000-0000-0000-000000007402','owner_admin',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007401'),true);

SELECT * FROM public.server_create_client_record('00000000-0000-0000-0000-000000007401','Client 74','Client 74 LLC','client.74@example.test');
SELECT * FROM public.server_create_project_record('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.clients WHERE display_name='Client 74'),'Project 74','USD');
SELECT * FROM public.server_owner_create_financial_account('00000000-0000-0000-0000-000000007401','Expense Cash 74','CASH','USD');

SELECT lives_ok($$ SELECT * FROM public.server_owner_update_expense_category('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.expense_categories WHERE code='OTHER'),1,'Other Owner Name','Owner edited description',true) $$,'Owner can edit seed category name and description');
SELECT results_eq($$ SELECT code, name, description, created_by IS NULL, updated_by IS NOT NULL FROM app.expense_categories WHERE code='OTHER' $$,$$ VALUES ('OTHER'::varchar,'Other Owner Name'::varchar,'Owner edited description'::text,true,true) $$,'category code stays stable and Owner update actor recorded');
SELECT throws_ok($$ SELECT set_config('app.expense_category_context','expense_category_owner_mutation',true); UPDATE app.expense_categories SET code='CHANGED' WHERE code='OTHER' $$,'23514','Expense category identity fields are immutable.','category code permanently immutable');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_project_expense('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),25,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30',' Vendor ',' inv-001 ',' Concrete bags ',' very private ') $$,'Owner creates draft project expense');
SELECT results_eq($$ SELECT expense_number::text, vendor_name::text, vendor_reference::text, description, private_notes, amount, currency_code FROM app.project_expenses $$,$$ VALUES ('EXP-000001'::text,'Vendor'::text,'INV-001'::text,'Concrete bags'::text,'very private'::text,25::numeric,'USD'::bpchar) $$,'expense facts normalize and EXP-000001 assigned');
SELECT results_eq($$ SELECT status::text, event_type::text, duplicate_fingerprint LIKE '%vendor_reference=INV-001%' FROM app.financial_events WHERE event_type='PROJECT_EXPENSE' $$,$$ VALUES ('DRAFT'::text,'PROJECT_EXPENSE'::text,true) $$,'financial event draft subtype and vendor duplicate fingerprint set');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_project_expense('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),25,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor','INV-001','Duplicate','notes') $$,'23505','Duplicate project expense.','nonblank vendor duplicate rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_project_expense('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),25,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor',NULL,'Same amount no ref','notes') $$,'null reference same project date currency amount allowed once');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_project_expense('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),25,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor','  ','Same amount blank ref','notes') $$,'blank reference same project date currency amount allowed again');
SELECT is((SELECT count(*)::integer FROM app.project_expenses WHERE vendor_reference IS NULL),2,'blank/null references do not collapse into duplicate rejection');
SELECT ok((SELECT bool_and(duplicate_fingerprint LIKE '%expense_number=EXP-%') FROM app.financial_events fe JOIN app.project_expenses pe ON pe.financial_event_id=fe.id WHERE pe.vendor_reference IS NULL),'null-reference fingerprints include expense number');

SELECT throws_ok($$ UPDATE app.project_expenses SET expense_number='EXP-999999' WHERE expense_number='EXP-000001' $$,'23514','Project expenses require trusted functions.','direct project expense update denied');
SELECT throws_ok($$ DELETE FROM app.project_expenses WHERE expense_number='EXP-000001' $$,'23514','Project expenses cannot be deleted.','direct delete denied');
SELECT throws_ok($$ SELECT * FROM public.server_owner_update_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),0,(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),30,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor','INV-002','Changed','notes') $$,'40001','Project expense version conflict.','stale expense update rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_update_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),1,(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),30,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor','INV-002','Changed','notes') $$,'draft update works');
SELECT results_eq($$ SELECT pe.expense_number::text, pe.amount, pe.vendor_reference::text, pe.description, fe.version_number FROM app.project_expenses pe JOIN app.financial_events fe ON fe.id=pe.financial_event_id WHERE pe.expense_number='EXP-000001' $$,$$ VALUES ('EXP-000001'::text,30::numeric,'INV-002'::text,'Changed'::text,2) $$,'draft update keeps immutable expense number and increments event version');

SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),2) $$,'Owner submits expense');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.submitted_by IS NOT NULL, fe.version_number FROM app.project_expenses pe JOIN app.financial_events fe ON fe.id=pe.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE pe.expense_number='EXP-000001' $$,$$ VALUES ('SUBMITTED'::text,'SUBMITTED'::text,true,3) $$,'submit moves event and transaction');
SELECT throws_ok($$ SELECT * FROM public.server_owner_approve_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),3) $$,'42501','Project expense requires different Owner approval.','same Owner approval rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_project_expense('00000000-0000-0000-0000-000000007402',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),3) $$,'different Owner approves and posts');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.approved_by=(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007402'), ft.posted_by=(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000007402'), fe.version_number FROM app.project_expenses pe JOIN app.financial_events fe ON fe.id=pe.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE pe.expense_number='EXP-000001' $$,$$ VALUES ('APPROVED'::text,'POSTED'::text,true,true,4) $$,'approval records different Owner and immutable approved status');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.project_expenses pe ON pe.financial_event_id=(SELECT financial_event_id FROM app.financial_transactions WHERE id=le.financial_transaction_id) WHERE pe.expense_number='EXP-000001'),2,'approval posts exactly two ledger entries');
SELECT results_eq($$ SELECT CASE WHEN la.code='CTRL-PROJECT-EXPENSE-USD' THEN la.code::text WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74') THEN 'PAYING-ASSET' ELSE la.code::text END, le.debit_amount, le.credit_amount, la.normal_side::text FROM app.ledger_entries le JOIN app.ledger_accounts la ON la.id=le.ledger_account_id JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.project_expenses pe ON pe.financial_event_id=ft.financial_event_id WHERE pe.expense_number='EXP-000001' ORDER BY le.line_no $$,$$ VALUES ('CTRL-PROJECT-EXPENSE-USD'::text,30::numeric,0::numeric,'DEBIT'::text),('PAYING-ASSET'::text,0::numeric,30::numeric,'DEBIT'::text) $$,'ledger debits Project Expense control and credits paying asset');
SELECT is((SELECT count(*)::integer FROM app.exchange_rates),0,'same-currency posting needs no exchange-rate row');
SELECT results_eq($$ SELECT total_expensed FROM public.server_owner_project_expense_totals('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74')) WHERE currency_code='USD' $$,$$ VALUES (30::numeric) $$,'posted project expense totals derive from posted control debits');
SELECT throws_ok($$ SELECT * FROM public.server_owner_update_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),4,(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),35,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor','INV-003','After approval','notes') $$,'23514','Project expense cannot be updated.','approved expense cannot be updated through workflow');
SELECT throws_ok($$ UPDATE app.ledger_entries SET memo='tamper' WHERE memo='Project expense debit' $$,'23514','Posted ledger entries are immutable.','posted ledger immutable');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_project_expense('00000000-0000-0000-0000-000000007402',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000001'),4) $$,'approval retry is idempotent');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.project_expenses pe ON pe.financial_event_id=ft.financial_event_id WHERE pe.expense_number='EXP-000001'),2,'approval retry does not duplicate ledger entries');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_project_expense('00000000-0000-0000-0000-000000007401',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000003'),1) $$,'submit second expense for rejection path');
SELECT throws_ok($$ SELECT * FROM public.server_owner_reject_project_expense('00000000-0000-0000-0000-000000007402',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000003'),2,'') $$,'23514','Rejection reason is required.','blank rejection denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_reject_project_expense('00000000-0000-0000-0000-000000007402',(SELECT financial_event_id FROM app.project_expenses WHERE expense_number='EXP-000003'),2,'not valid') $$,'different Owner rejects submitted expense');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.rejection_reason IS NOT NULL FROM app.project_expenses pe JOIN app.financial_events fe ON fe.id=pe.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE pe.expense_number='EXP-000003' $$,$$ VALUES ('REJECTED'::text,'REJECTED'::text,true) $$,'reject marks event and transaction');
SELECT is((SELECT count(*)::integer FROM app.activity_logs WHERE action LIKE 'project_expense_%'),8,'safe project expense activities logged');
SELECT ok(NOT EXISTS (SELECT 1 FROM app.activity_logs WHERE action LIKE 'project_expense_%' AND (previous_values::text ILIKE '%very private%' OR new_values::text ILIKE '%very private%' OR metadata::text ILIKE '%very private%' OR previous_values::text ILIKE '%not valid%' OR new_values::text ILIKE '%not valid%' OR metadata::text ILIKE '%not valid%')),'private notes and rejection text omitted from activity logs');
SELECT throws_ok($$ SELECT setval('app.project_expense_number_seq',999999,true); SELECT * FROM public.server_owner_create_project_expense('00000000-0000-0000-0000-000000007401',(SELECT id FROM app.projects WHERE name='Project 74'),(SELECT id FROM app.expense_categories WHERE code='OTHER'),1,'USD',(SELECT id FROM app.financial_accounts WHERE name='Expense Cash 74'),DATE '2026-07-30','Vendor',NULL,'Overflow','notes') $$,'2200H','nextval: reached maximum value of sequence "project_expense_number_seq" (999999)','expense numbering stops before seven digits');

SELECT * FROM finish();
ROLLBACK;
